    std: Option<Arc<StdFile>>,
    inner: Mutex<Inner>,
    max_buf_size: usize,
    opt_read: bool,
    opt_write: bool,
    opt_append: bool,
    opt_truncate: bool,
    opt_create: bool,
    opt_create_new: bool,
